source.loginUrl:
function login(b) {
    if (b == undefined) return true;
    info = result;
    so = getUrl();
    pwd = info.密码;
    imgurl = so + '/user/user/verify.html?' + Math.random();

    if (b) {
        url = so + '/user/user/login.html,';
        body = `username=${info.用户名}&password=${pwd}&code=${java.getVerificationCode(imgurl)}`;
    } else {
    	code=String(info.邮箱验证码)||java.getVerificationCode(sentEmail(info.邮箱))
        url = so + '/qs_register_go.php,';
        body = `name=${info.用户名}&email=${info.邮箱}&invite_code=${info.邀请码}&password=${pwd}&repassword=${pwd}&email_code=${code}`;
    }
    post = JSON.stringify({
        "body": String(body),
        "method": "POST"
    });
    url += post;
    result = java.ajax(url);
    java.log(result);
    msg=result.match(/msg\s*=\s*"([^"]+)"/)
    java.toast(msg?msg[1]:"未知信息，请查看日志");
    c = cookie.getCookie(getUrl());
    source.setVariable(c);
}

function D(){
cookie.removeCookie(getUrl());
source.setVariable('');
java.toast('登出成功')
	}
T=()=>{
java.toast('密码：'+result.密码)
}

A = (x) => {
	eval(String(java.base64Decode(jk)));
}
H = () => {
	eval(String(java.base64Decode(gx)));
}

K = () => {
	url = getUrl()
	java.toast('当前接口:' + '【' + source.getVariable() + '】' + '\n' + url)
}

