"言情小说","其他类型","经部","史书",
"子部","集部","四库之外","古典书籍",
"诗歌","宋词",["排行","/top/allvisit"],
["新书","/top/postdate"],
["完本小说","/fulltop/allvisit"]];

sort=book.map((a,i)=>{
	if(i<book.length-3){
		i++; title=a;
		url=`/sort/${i}/{{page}}.html`;
		}else{
			title=String(a[0]);
			url=`${a[1]}/{{page}}.html`;
			}
			json=({
    "title": title,
    "url": url,
    "style": {
      "layout_flexGrow": 1,
       "layout_flexBasisPercent": 0.25,
    }
   });
   return json
	});

JSON.stringify(sort)

